135	/// Minimal JSON Schema subset validator (M13 T15, spec §7.3
136	/// `response_schema`). No JSON Schema crate is approved for this workspace
137	/// (ADR-002/ADR-003 approve no such dependency), so per the plan's redesign
138	/// trigger this validates a narrow, explicitly-scoped subset instead of
139	/// pretending arbitrary JSON Schema is enforced: `type`, `enum`,
140	/// `properties` (object member schemas), `required` (object member
141	/// presence), and `items` (array element schema, applied uniformly). Any
142	/// other keyword is not enforced. `output` is treated as untrusted JSON
143	/// text; malformed JSON never validates.
144	pub fn validate_response_schema(schema: &serde_json::Value, output: &str) -> bool {
145	    match serde_json::from_str::<serde_json::Value>(output) {
146	        Ok(value) => schema_matches(schema, &value),
147	        Err(_) => false,
148	    }
149	}
150	
151	fn schema_matches(schema: &serde_json::Value, value: &serde_json::Value) -> bool {
152	    let Some(schema_obj) = schema.as_object() else {
153	        return true;
154	    };
155	    if let Some(allowed) = schema_obj.get("enum").and_then(|v| v.as_array()) {
156	        if !allowed.contains(value) {
157	            return false;
158	        }
159	    }
160	    if let Some(expected_type) = schema_obj.get("type").and_then(|v| v.as_str()) {
161	        if !json_type_matches(expected_type, value) {
162	            return false;
163	        }
164	    }
165	    if let Some(properties) = schema_obj.get("properties").and_then(|v| v.as_object()) {
166	        let Some(object) = value.as_object() else {
167	            return false;
168	        };
169	        for (key, sub_schema) in properties {
170	            if let Some(field) = object.get(key) {
171	                if !schema_matches(sub_schema, field) {
172	                    return false;
173	                }
174	            }
175	        }
176	    }
177	    if let Some(required) = schema_obj.get("required").and_then(|v| v.as_array()) {
178	        let Some(object) = value.as_object() else {
179	            return false;
180	        };
181	        if !required
182	            .iter()
183	            .filter_map(|name| name.as_str())
184	            .all(|name| object.contains_key(name))
185	        {
186	            return false;
187	        }
188	    }
189	    if let Some(items_schema) = schema_obj.get("items") {
190	        let Some(array) = value.as_array() else {
191	            return false;
192	        };
193	        if !array.iter().all(|item| schema_matches(items_schema, item)) {
194	            return false;
195	        }
196	    }
197	    true
198	}
199	
200	fn json_type_matches(expected: &str, value: &serde_json::Value) -> bool {
201	    match expected {
202	        "object" => value.is_object(),
203	        "array" => value.is_array(),
204	        "string" => value.is_string(),
205	        "number" => value.is_number(),
206	        "integer" => value.is_i64() || value.is_u64(),
207	        "boolean" => value.is_boolean(),
208	        "null" => value.is_null(),
209	        // Unrecognized type keyword: not enforced rather than falsely rejected.
210	        _ => true,
211	    }
212	}
