240	/// Build a capability claim bounded to what `permitted` actually grants.
241	/// Never elevates: uses the natural class for the capability's real status
242	/// when that class is permitted; otherwise downgrades to the highest
243	/// permitted class below it, capping status to that class's evidence rung.
244	/// Missing permission caps, never elevates (§10.2, §16.1, T13.1, T13.2).
245	fn capped_capability_claim(
246	    cap: &CapabilityInfo,
247	    snap_ref: &str,
248	    permitted: &[ClaimClass],
249	) -> Option<GroundedClaim> {
250	    use ClaimClass::{DeclaredCapability, DemonstratedCapability, InstalledCapability};
251	    let natural_class = match cap.status {
252	        ClaimStatus::Demonstrated | ClaimStatus::Validated => DemonstratedCapability,
253	        ClaimStatus::Installed | ClaimStatus::Available => InstalledCapability,
254	        _ => DeclaredCapability,
255	    };
256	    let class = if permitted.contains(&natural_class) {
257	        natural_class
258	    } else if natural_class == DemonstratedCapability && permitted.contains(&InstalledCapability) {
259	        InstalledCapability
260	    } else if permitted.contains(&DeclaredCapability) {
261	        DeclaredCapability
262	    } else {
263	        lowest_permitted_capability_class(permitted)?
264	    };
265	    let ceiling = capability_class_ceiling(&class);
266	    let status = if cap.status <= ceiling {
267	        cap.status.clone()
268	    } else {
269	        ceiling
270	    };
271	    let statement = format!(
272	        "{} is {}{}",
273	        cap.name,
274	        format!("{status:?}").to_lowercase(),
275	        if cap.flags.unavailable_in_environment {
276	            " (unavailable in environment)"
277	        } else {
278	            ""
279	        }
280	    );
281	    Some(GroundedClaim {
282	        claim_id: format!("claim_{}", cap.name),
283	        claim_class: class,
284	        subject: cap.name.clone(),
285	        status,
286	        flags: cap.flags.clone(),
287	        statement,
288	        snapshot_ref: snap_ref.to_owned(),
289	        evidence_refs: cap.evidence_refs.clone(),
290	        settlement_refs: cap.settlement_refs.clone(),
291	        capability_record_ref: cap.capability_record_ref.clone(),
292	        limitations: cap.limitations.clone(),
293	        authored_by: Some(THOTH_ACTOR_ID.into()),
294	    })
295	}
