322	/// Derive claims from the snapshot within the permitted class boundary.
323	/// The query executor cannot touch non-permitted regions (§10.3). Total over
324	/// `QuestionKind`: every reachable arm (all but `AskWhyDenied`, handled
325	/// earlier) always emits at least one claim when `permitted` is non-empty
326	/// (guaranteed by the caller's deny-all-when-empty gate), so `Answered`
327	/// never carries an unexplained empty claim set (T13.3).
328	fn derive_claims(
329	    kind: &QuestionKind,
330	    subject: &str,
331	    snapshot: &dyn SnapshotView,
332	    permitted: &[ClaimClass],
333	) -> Vec<GroundedClaim> {
334	    let mut claims = Vec::new();
335	    let snap_ref = snapshot.snapshot_ref();
336	
337	    match kind {
338	        QuestionKind::AskCapability | QuestionKind::AskProjectionSupport => {
339	            match snapshot.capability(subject) {
340	                Some(cap) => {
